SELECT V.ID, V.YT_VIDEO_ID, V.TITULO, V.PUBLICADO_EM, V.DURACAO_SEG, V.ORIGEM, V.STATUS, C.NOME CANAL, V.RESUMO, (SELECT GROUP_CONCAT(CONCAT(T.NOME, '=', IFNULL(VT.MOMENTOS, '')) ORDER BY T.NOME SEPARATOR '|') FROM VIDEO_TEMAS VT JOIN TEMAS T ON T.ID = VT.TEMA_ID WHERE VT.VIDEO_ID = V.ID) TEMAS, (SELECT GROUP_CONCAT(DISTINCT P.TITULO ORDER BY P.ORDEM SEPARATOR ' | ') FROM PLAYLIST_VIDEOS PV JOIN PLAYLISTS P ON P.ID = PV.PLAYLIST_ID WHERE PV.YT_VIDEO_ID = V.YT_VIDEO_ID) PLAYLISTS, (SELECT GROUP_CONCAT(CONCAT(PR.TIPO, ': ', IFNULL(PR.TITULO, '')) ORDER BY PR.SEGUNDO SEPARATOR ' | ') FROM PRATICAS PR WHERE PR.VIDEO_ID = V.ID) PRATICAS FROM VIDEOS V JOIN CANAIS C ON C.ID = V.CANAL_ID WHERE V.STATUS <> 'FORA' AND (V.STATUS <> 'FORA_TEMA' OR '{{status}}' = 'FORA_TEMA') AND ({{canalId}} = 0 OR V.CANAL_ID = {{canalId}}) AND ('{{status}}' = '' OR V.STATUS = '{{status}}') AND ({{nTemas}} = 0 OR V.ID IN (SELECT XT.VIDEO_ID FROM VIDEO_TEMAS XT WHERE FIND_IN_SET(XT.TEMA_ID, '{{temas}}') GROUP BY XT.VIDEO_ID HAVING COUNT(DISTINCT XT.TEMA_ID) = {{nTemas}})) AND ({{nPlay}} = 0 OR V.YT_VIDEO_ID IN (SELECT XP.YT_VIDEO_ID FROM PLAYLIST_VIDEOS XP WHERE FIND_IN_SET(XP.PLAYLIST_ID, '{{playlists}}') GROUP BY XP.YT_VIDEO_ID HAVING COUNT(DISTINCT XP.PLAYLIST_ID) = {{nPlay}})) AND ({{nPrat}} = 0 OR V.ID IN (SELECT XR.VIDEO_ID FROM PRATICAS XR WHERE XR.CONSELHO = 0 AND FIND_IN_SET(XR.JEITO, '{{praticas}}') GROUP BY XR.VIDEO_ID HAVING COUNT(DISTINCT XR.JEITO) = {{nPrat}})) AND ('{{origem}}' = '' OR V.ORIGEM = '{{origem}}') AND ('{{meu}}' = '' OR ('{{meu}}' = 'FAV' AND V.FAVORITO = 1) OR ('{{meu}}' = 'VISTO' AND V.ASSISTIDO_EM IS NOT NULL) OR ('{{meu}}' = 'NAOVISTO' AND V.ASSISTIDO_EM IS NULL)) AND V.ID > {{depois}} ORDER BY V.ID LIMIT 500